async function aiFitRequest(packet){const c=aiConnection();let fitted=EpiAIContext.prepareRequest(packet);const cacheKey=c.endpoint+'|'+String(packet.requestId),wire=()=>JSON.stringify({...fitted,clientTimeoutMs:120000}),cached=aiFittedRequests.get(cacheKey);if(cached?.wire===wire())return fitted;let inspectionCalls=0;const beforeHistory=fitted.history.length;for(;;){inspectionCalls++;const response=await fetch(aiEndpoint(c.endpoint)+'/inspect',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+c.code},body:wire(),signal:AbortSignal.timeout(20000),credentials:'omit',cache:'no-store'});let audit;try{audit=await response.json();}catch{throw Error('The free request check returned an unreadable reply. No paid generation was sent.');}const tooFull=response.status===413&&/complete request|context too large/i.test(String(audit.error||'')),tooLittle=response.ok&&Number.isFinite(audit.providerRequest?.max_tokens)&&audit.providerRequest.max_tokens<512;if((tooFull||tooLittle)&&fitted.history.length){fitted={...fitted,history:fitted.history.slice(1)};if(fitted.history[0]?.role==='assistant')fitted.history=fitted.history.slice(1);continue;}if(!response.ok)throw Error((audit.error||'The free request check failed.')+' No paid generation was sent.');if(audit.paidGeneration!==false)throw Error('The backend does not support a free request check. No paid generation was sent.');if(tooLittle)throw Error('The recorded facts leave too little room for a reply. No paid generation was sent.');aiContextFitStats.push({requestId:packet.requestId,beforeHistory,afterHistory:fitted.history.length,inspectionCalls,replyTokenRoom:audit.providerRequest?.max_tokens,providerMessageBytes:encodeURIComponent(JSON.stringify(audit.providerRequest?.messages||[])).replace(/%[A-F0-9]{2}/g,'x').length});if(aiContextFitStats.length>20)aiContextFitStats.shift();aiFittedRequests.set(cacheKey,{wire:wire()});if(aiFittedRequests.size>16)aiFittedRequests.delete(aiFittedRequests.keys().next().value);return fitted;}}
