async function aiCheckUsage(){try{aiUsage=await aiFetch('/usage');aiBackendProtocol=aiUsage.protocolVersion||'unknown';aiStatus='Connected · '+aiUsage.model+' · Backend '+aiBackendProtocol+(aiBackendProtocol!==AI_REQUIRED_PROTOCOL?' · AI integration update required; the game and AI backend are different deployments.':' · Integration contract matches.');}catch(error){aiStatus=error instanceof TypeError?'Cannot reach the AI backend. Check its address and deployment.':error.message;}render();}
document.addEventListener('click',event=>{const b=event.target.closest?.('button');if(!b)return;aiInputText=String(b.textContent||'').trim();queueMicrotask(()=>{aiInputText='';});},true);
document.addEventListener('click',event=>{if(event.target.closest?.('[data-ai-usage]'))aiCheckUsage();if(event.target.closest?.('[data-ai-disconnect]')){sessionStorage.removeItem(AI_CODE_KEY);save.settings||={};save.settings.aiEnabled=false;aiStatus='AI disconnected. Ordinary gameplay is available.';store();render();}});
document.addEventListener('submit',event=>{if(event.target.id!=='aiConnectionForm')return;event.preventDefault();try{const endpoint=aiEndpoint(document.getElementById('aiBackend').value),code=document.getElementById('aiAccessCode').value.trim();if(code&&code.length<32)throw Error('Use the backend’s game access code of at least 32 characters.');if(code)sessionStorage.setItem(AI_CODE_KEY,code);localStorage.setItem(AI_CONFIG_KEY,endpoint);save.settings||={};save.settings.aiEnabled=document.getElementById('aiEnable').checked;save.settings.aiNarration=document.getElementById('aiNarrate').checked;save.settings.footwearNarration=document.getElementById('aiFootwearNarrate').checked;aiStatus='Connection saved. Check connection and usage before starting a conversation.';store();render();}catch(error){aiStatus=error.message;render();}});

function aiErinAuthority(){const e=EpiErin.state(save),a=EpiErinLife.runtime(save).actor,m=EpiFormMinds.mind(save,'erin'),at=save.worldClock?.minutes??0,pause=a.pauseUntil>at,player=e.mastered||m.influence===0||pause,forced=!!a.forcedRoutine||!!a.pending&&!a.consent;return {mode:a.delegation?.status==='active'?'voluntarily-form-led':player?'player-led':m.influence>=75||forced?'form-led':'contested',basis:e.mastered?'mastered':pause?'temporary agreed/resisted pause':m.influence===0?'zero influence':forced?'active resolved form routine':m.influence>=75?'high unmastered influence':'recorded influence and resolved contests',currentPhysicalAction:e.activities?.current?.title||a.pending?.action||a.forcedRoutine?.goal||null,delegation:a.delegation?.status==='active'?a.delegation:null,delegated:!!a.consent||a.delegation?.status==='active',agreedPauseUntil:pause?a.pauseUntil:null,dialogueCannotMoveBody:true};}
function aiErinExperiences(){const e=EpiErin.state(save),t=save.worldClock?.minutes??0,work=e.workday?.days?.[Math.floor(t/1440)],jobs=Object.values(save.world?.technologyCenter?.floorServices?.jobs||{}).filter(j=>j.status==='completed');return {ongoingActivity:e.activities?.current||null,recentReading:e.lastReadAt!=null&&t-e.lastReadAt<120,lastActivity:e.activities?.history?.at(-1)||null,worldDay:Math.floor(t/1440)+1,recentCompletedWork:jobs.slice(-3).map(j=>j.kind),workedToday:!!work,masteryProgress:e.internal?.progress??0,relationship:e.relationship,cooperativeRelationshipTarget:100,dailyRelationshipCap:5,lastPhysicalEvents:(e.life?.history||[]).filter(x=>x.outcome==='completed').slice(-3).map(x=>({action:x.action,room:x.room,at:x.at})),memoryLimit:'Only supplied events are known; do not invent a week of specific memories or unseen coworkers.'};}

function aiErinResolvedDialogue(){const d=EpiErinLife.runtime(save).actor.dialogue?.lastOutcome,at=save.worldClock?.minutes??0;return d?.actionId&&at>=d.at&&at-d.at<=2?{actionId:d.actionId,outcome:d.outcome,at:d.at}:null;}
